import logging
from base64 import b64encode
from typing import Any, Union
from xml.etree.ElementTree import fromstring

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.http_client import HttpPdu
from taf.hw.pdu.exceptions import BadDeviceStatus


class Lantick(HttpPdu):
    _GET_STATUS_OFF = "0"
    _GET_STATUS_ON = "1"

    def __init__(
            self,
            host: str,
            login: str,
            password: str,
            timeout: Union[float, int] = 20,
            **kwargs: Any
    ) -> None:
        super().__init__(host, timeout)
        credentials = b64encode(f"{login}:{password}".encode()).decode()
        self.headers = {"Authorization": "Basic " + credentials}
        self.status_url = "http://" + host + "/status.xml"
        self.host = host
        self._http_proxy = (
            {"http": kwargs.get("http_proxy")} if kwargs.get("http_proxy") else None
        )

    def power_off(self, port):
        response = self.set_pdu(port, "off")
        expected_response = "0"
        if expected_response not in self._parse_response(response, port):
            raise RuntimeError(
                f"Unexpected response from device. Expected {expected_response}, found {response}"
            )

    def power_on(self, port):
        response = self.set_pdu(port, "on")
        expected_response = "1"
        if expected_response not in self._parse_response(response, port):
            raise RuntimeError(
                f"Unexpected response from device. Expected {expected_response}, found {response}"
            )

    def set_pdu(self, port, label):
        request = self._build_request_url(port=port, label=label)
        response = self._send_request(request)
        return response

    def _send_request(self, url, method="POST", headers=None, data=None, params=None):
        if headers is None:
            headers = self.headers
        return super(Lantick, self)._send_request(
            url=url,
            method=method,
            headers=headers,
            data=data,
            params=params,
            proxies=self._http_proxy,
        )

    def _build_request_url(self, port, label):
        if label:
            return f"http://{self.host}/stat.php?{label}={port}"
        return self.status_url

    def _parse_response(self, response, port):
        """Parse HTTP GET/POST response from PDU server."""
        root = fromstring(response.content)
        on_settings = root.findall("on")[0].text
        index = -1 * port
        if on_settings[index] in ["1", "0"]:
            return on_settings[index]
        else:
            logging.critical(
                f"Expected 0 or 1 in response, received response: {on_settings}"
            )
            raise BadDeviceStatus("Unexpected response from the device.")

    @property
    def _port_setting(self):
        return {
            DeviceStatus.OFF: self._GET_STATUS_OFF,
            DeviceStatus.ON: self._GET_STATUS_ON,
        }
